// Cookie-gated Channel Performance dashboard. Custom branded login page
// (not the browser's native Basic Auth dialog) posts to this same
// endpoint; on success we set an HttpOnly cookie and redirect back to a
// GET of this same URL. Dashboard HTML is stored as base64 here (not a
// separate static file) so the function bundle never depends on Vercel
// including an extra file at build time.
import { createHash } from "crypto";

const PASSWORD = "500demos";
const COOKIE_NAME = "cp_auth";
const COOKIE_SALT = "tranzact-channel-performance-v1";
const HTML_B64 = "";

function expectedToken() {
  return createHash("sha256").update(PASSWORD + COOKIE_SALT).digest("hex");
}

function parseCookies(header) {
  const out = {};
  (header || "").split(";").forEach((part) => {
    const idx = part.indexOf("=");
    if (idx === -1) return;
    const k = part.slice(0, idx).trim();
    const v = part.slice(idx + 1).trim();
    if (k) out[k] = decodeURIComponent(v);
  });
  return out;
}

function isAuthed(req) {
  const cookies = parseCookies(req.headers.cookie);
  return cookies[COOKIE_NAME] === expectedToken();
}

function setAuthCookie(res) {
  const token = expectedToken();
  res.setHeader(
    "Set-Cookie",
    `${COOKIE_NAME}=${token}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=2592000`
  );
}

function loginPageHtml(showError) {
  return `<!doctype html><html><head><meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Channel Performance</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Montserrat:wght@600;700&family=Poppins:wght@500;600;700&family=Open+Sans:wght@400;500;600;700&display=swap">
<style>
  :root {
    --bg: #F5F4EF; --surface: #FFFFFF; --surface-2: #FBFAF7; --border: #E4E2D9;
    --ink: #0E0F0C; --ink-2: #45463F; --muted: #858A8E;
    --accent: #DA5D37; --accent-ink: #FFFFFF; --bad: #B23A2E;
    --shadow: 0 1px 2px rgba(14,15,12,0.04), 0 6px 16px rgba(14,15,12,0.05), 0 20px 44px rgba(14,15,12,0.08);
  }
  @media (prefers-color-scheme: dark) {
    :root {
      --bg: #0E0F0C; --surface: #1C1A1A; --surface-2: #201E1C; --border: #2E2C28;
      --ink: #F5F3EE; --ink-2: #C7C4BB; --muted: #9C9A93;
      --accent: #E37350; --accent-ink: #0E0F0C; --bad: #E06A5C;
      --shadow: 0 1px 2px rgba(0,0,0,0.3), 0 8px 24px rgba(0,0,0,0.35), 0 24px 60px rgba(0,0,0,0.45);
    }
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; height: 100%; }
  body {
    background: var(--bg); color: var(--ink);
    font-family: 'Open Sans', Inter, system-ui, sans-serif;
    -webkit-font-smoothing: antialiased;
    display: flex; align-items: center; justify-content: center;
    min-height: 100vh; padding: 24px;
  }
  .card {
    width: 100%; max-width: 380px; background: var(--surface);
    border: 1px solid var(--border); border-radius: 16px;
    padding: 36px 32px 32px; box-shadow: var(--shadow);
    text-align: center;
  }
  .eyebrow {
    font-family: 'Poppins', sans-serif; font-weight: 600; font-size: 11.5px;
    letter-spacing: 0.1em; text-transform: uppercase; color: var(--accent); margin: 0 0 8px;
  }
  h1 {
    font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 22px;
    margin: 0 0 6px; letter-spacing: -0.01em;
  }
  .subtitle { font-size: 13px; color: var(--muted); margin: 0 0 28px; line-height: 1.5; }
  form { display: flex; flex-direction: column; gap: 14px; }
  input[type="password"] {
    width: 100%; font: inherit; font-size: 15px; color: var(--ink);
    background: var(--surface-2); border: 1px solid var(--border); border-radius: 9px;
    padding: 12px 14px; text-align: center; letter-spacing: 0.02em;
  }
  input[type="password"]:focus { outline: 2px solid var(--accent); outline-offset: 1px; }
  input[type="password"].err { border-color: var(--bad); animation: shake 0.35s; }
  @keyframes shake {
    0%, 100% { transform: translateX(0); }
    20%, 60% { transform: translateX(-6px); }
    40%, 80% { transform: translateX(6px); }
  }
  button {
    appearance: none; border: none; cursor: pointer;
    font-family: 'Poppins', sans-serif; font-weight: 600; font-size: 14px;
    background: var(--accent); color: var(--accent-ink);
    border-radius: 9px; padding: 12px 14px;
  }
  button:hover { filter: brightness(1.04); }
  .error-msg {
    font-size: 12.5px; color: var(--bad); font-weight: 600; margin: -4px 0 0;
    __ERROR_DISPLAY__
  }
  .footnote { font-size: 11px; color: var(--muted); margin-top: 22px; }
</style>
</head><body>
  <div class="card">
    <p class="eyebrow">TranZact &middot; Growth</p>
    <h1>Channel Performance</h1>
    <p class="subtitle">This dashboard is private. Enter the password to continue.</p>
    <form method="POST" action="/api/channel-performance">
      <input type="password" name="password" placeholder="Password" autofocus class="__INPUT_ERR_CLASS__">
      <p class="error-msg">Incorrect password &mdash; try again.</p>
      <button type="submit">Unlock dashboard</button>
    </form>
    <p class="footnote">TranZact internal &middot; not for external sharing</p>
  </div>
</body></html>`.replace('__ERROR_DISPLAY__', showError ? '' : 'display:none;').replace('__INPUT_ERR_CLASS__', showError ? 'err' : '');
}

export default function handler(req, res) {
  res.setHeader("X-Robots-Tag", "noindex, nofollow, noarchive");

  if (req.method === "POST") {
    const body = req.body || {};
    const password =
      typeof body === "string" ? new URLSearchParams(body).get("password") : body.password;
    if (password === PASSWORD) {
      setAuthCookie(res);
      res.statusCode = 302;
      res.setHeader("Location", "/api/channel-performance");
      return res.end();
    }
    res.setHeader("Content-Type", "text/html; charset=utf-8");
    return res.status(401).send(loginPageHtml(true));
  }

  if (!isAuthed(req)) {
    res.setHeader("Content-Type", "text/html; charset=utf-8");
    return res.status(200).send(loginPageHtml(false));
  }

  const html = Buffer.from(HTML_B64, "base64").toString("utf8");
  res.setHeader("Content-Type", "text/html; charset=utf-8");
  res.setHeader("Cache-Control", "private, no-store");
  res.status(200).send(html);
}
